// Extraire la traduction Claude
const input = $input.first().json;
const prevData = $('Loop Commentaries').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

let claudeTranslation = '';
let claudeError = null;
let claudeUsage = { input_tokens: 0, output_tokens: 0, total_tokens: 0 };

if (statusCode >= 400 || data.type === 'error' || data.error) {
  claudeError = data.error?.message || data.message || `Erreur Claude HTTP ${statusCode}`;
} else if (data.content?.[0]?.text) {
  claudeTranslation = data.content[0].text.trim();
  claudeUsage = {
    input_tokens: data.usage?.input_tokens || 0,
    output_tokens: data.usage?.output_tokens || 0,
    total_tokens: (data.usage?.input_tokens || 0) + (data.usage?.output_tokens || 0)
  };
}

return [{
  json: {
    ...prevData,
    claudeTranslation: claudeTranslation,
    claudeError: claudeError,
    claudeUsage: claudeUsage
  }
}];

// Extraire et combiner les résultats
const input = $input.first().json;
const prevData = $('Claude OK?').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

let gptVerification = {
  my_translation: prevData.claudeTranslation,
  approved: true,
  confidence: 0.8,
  issues: []
};
let gptUsage = { input_tokens: 0, output_tokens: 0, total_tokens: 0 };

if (statusCode < 400 && data.choices?.[0]?.message?.content) {
  try {
    gptVerification = JSON.parse(data.choices[0].message.content);
    gptUsage = {
      input_tokens: data.usage?.prompt_tokens || 0,
      output_tokens: data.usage?.completion_tokens || 0,
      total_tokens: (data.usage?.prompt_tokens || 0) + (data.usage?.completion_tokens || 0)
    };
  } catch (e) {}
}

const finalTranslation = gptVerification.approved ? prevData.claudeTranslation : (gptVerification.my_translation || prevData.claudeTranslation);

return [{
  json: {
    ...prevData,
    gptVerification: gptVerification,
    gptUsage: gptUsage,
    finalTranslation: finalTranslation,
    confidence: gptVerification.confidence || 0.8,
    approved: gptVerification.approved
  }
}];

// Préparer les données pour la mise à jour du job
const input = $input.first().json;
const prevData = $('Extract GPT').first().json;

const commentaryIndex = prevData.commentaryIndex;
const totalCommentaries = prevData.totalCommentaries;
const isComplete = commentaryIndex + 1 >= totalCommentaries;

const claudeUsage = prevData.claudeUsage || { input_tokens: 0, output_tokens: 0, total_tokens: 0 };
const gptUsage = prevData.gptUsage || { input_tokens: 0, output_tokens: 0, total_tokens: 0 };

const tokens = {
  claude: claudeUsage,
  gpt: gptUsage,
  total: {
    input_tokens: (claudeUsage.input_tokens || 0) + (gptUsage.input_tokens || 0),
    output_tokens: (claudeUsage.output_tokens || 0) + (gptUsage.output_tokens || 0),
    total_tokens: (claudeUsage.total_tokens || 0) + (gptUsage.total_tokens || 0)
  }
};

return [{
  json: {
    ...prevData,
    isComplete: isComplete,
    updatePayload: isComplete ? {
      status: 'completed',
      translations_saved: commentaryIndex + 1,
      tokens: tokens
    } : {
      status: 'in_progress',
      current_commentary: commentaryIndex + 1,
      translations_saved: commentaryIndex + 1,
      tokens: tokens
    }
  }
}];

// Retourner au loop
const prevData = $('Prepare Update').first().json;

return [{
  json: {
    continue: !prevData.isComplete,
    commentaryIndex: prevData.commentaryIndex,
    totalCommentaries: prevData.totalCommentaries,
    jobId: prevData.jobId,
    callbackUrl: prevData.callbackUrl,
    isComplete: prevData.isComplete,
    updatePayload: prevData.updatePayload
  }
}];

// Préparer la mise à jour pour erreur
const input = $input.first().json;

const commentaryIndex = input.commentaryIndex;
const totalCommentaries = input.totalCommentaries;
const isComplete = commentaryIndex + 1 >= totalCommentaries;

return [{
  json: {
    ...input,
    isComplete: isComplete,
    updatePayload: isComplete ? {
      status: 'completed',
      translations_saved: commentaryIndex,
      error: input.claudeError
    } : {
      status: 'in_progress',
      current_commentary: commentaryIndex + 1,
      translations_saved: commentaryIndex,
      last_error: input.claudeError
    }
  }
}];

// Check if completed and needs callback
const prevData = $('Prepare Error Update').first().json;

return [{
  json: {
    continue: !prevData.isComplete,
    commentaryIndex: prevData.commentaryIndex,
    totalCommentaries: prevData.totalCommentaries,
    jobId: prevData.jobId,
    callbackUrl: prevData.callbackUrl,
    isComplete: prevData.isComplete,
    updatePayload: prevData.updatePayload,
    hasError: true,
    errorMessage: prevData.claudeError
  }
}];

// Collect final result from loop completion
const parseInput = $('Parse Input').first().json;

return [{
  json: {
    jobId: parseInput.jobId,
    callbackUrl: parseInput.callbackUrl,
    textName: parseInput.textName,
    chapter: parseInput.chapter,
    commentariesCount: parseInput.commentariesCount,
    status: 'completed'
  }
}];

// Signature deleguee au noeud Crypto natif qui suit : le bac a sable n8n
// interdit require('crypto'). Cf. n8n-workflows#476.
// RFC-040: Prepare success callback with HMAC signature
const input = $input.first().json;

const body = {
  success: true,
  job_id: input.jobId,
  status: 'completed',
  data: {
    text_name: input.textName,
    chapter: input.chapter,
    translations_completed: input.commentariesCount
  }
};

const corps_json = JSON.stringify(body);

return [{
  json: {
    callbackUrl: input.callbackUrl,
    body: body,
    corps_json: corps_json,
    rappel_signable: !!$env.N8N_WEBHOOK_SECRET
  }
}];

