// interdit require('crypto'). Cf. n8n-workflows#476.
// RFC-040: Prepare error callback with HMAC signature
const input = $input.first().json;

const body = {
  success: false,
  job_id: input.jobId,
  status: 'completed_with_errors',
  error: {
    message: input.errorMessage || 'Unknown error during processing',
    commentary_index: input.commentaryIndex,
    total_commentaries: input.totalCommentaries
